 const l=await context(cases[0]);const issued=await(await fetch(fx.base+'/auth/issue-code',{method:'POST',headers:{'X-Agend-Token':fx.fm.webToken}})).json();await l.p.goto(fx.base+'/signin');await l.p.fill('#code',issued.code);await l.p.click('#go');await l.p.waitForURL(fx.base+'/ui');await l.p.goto(fx.base+'/settings/hub');await l.p.fill('#hubAddress',memberOrigin);await l.p.fill('#hubCode',code);await l.p.locator('#hub-connect form button[type=submit]').click();await apply(l.p,'.hub-local-confirm');await n.p.getByRole('button',{name:'They match',exact:true}).waitFor();const a=(await n.p.locator('[data-quick-pairing] .hub-fp-groups').last().innerText()).replace(/\s/g,''),b=(await l.p.locator('.hub-pending .hub-fp-groups').innerText()).replace(/\s/g,'');check('phone-control exact fingerprints',a===b&&a.length===32);await l.p.locator('.hub-local-confirm').click();await apply(l.p,'.hub-local-confirmed, .hub-paired');await n.p.getByRole('button',{name:'They match',exact:true}).click();await n.p.getByText('Connected',{exact:true}).waitFor({timeout:20000});await memberStart;await waitFor(()=>online,'phone-control full member online');
